                    candidates.append((abs(rr-r)+abs(cc-c), rr, cc))
        if candidates:
            _, er, ec = min(candidates)
            dr = 0 if er == r else (1 if er > r else -1)
            dc = 0 if ec == c else (1 if ec > c else -1)
            rr, cc = r + dr, c + dc
